import type { Kysely } from "kysely";

import type { Database, JsonObject } from "../db/schema.ts";
import type { Location } from "../enrichment/geo.ts";
import type { Client } from "../enrichment/user-agent.ts";

export interface Utm {
  source?: string;
  medium?: string;
  campaign?: string;
  term?: string;
  content?: string;
}

/** An event that has already passed validation (step 2 adds the endpoint that validates). */
export interface NewEvent {
  /** Generated by the sender; makes retries safe. */
  eventId: string;
  name: string;
  /** Sender's clock. */
  occurredAt: Date;
  /** Page path; left out for a server-side event that names no page. */
  path?: string;
  referrer?: string;
  utm?: Utm;
  properties?: JsonObject;
  /** Browser, OS, and device, from the request's User-Agent. */
  client?: Client;
  /** Country, region, and city, from the request's IP address. */
  location?: Location;
  /** Daily cookieless visitor ID (see visitors/visitor-ids.ts). */
  visitorId?: string;
  /** Where the app runs, in lower case; "production" when left out (collection/environment.ts). */
  environment?: string;
  /** The app's version, such as "1.4.2". */
  release?: string;
  /** The site's own ID for the signed-in user (collection/identity.ts). */
  userId?: string;
}

export interface StoreResult {
  /** Events stored for the first time. */
  inserted: number;
  /** Events skipped because this project already has an event with the same ID. */
  duplicates: number;
}

/**
 * Stores events for one project in a single statement, so either all new
 * events are saved or none are.
 *
 * An event whose ID is already stored is skipped, not stored again. Senders
 * retry when they do not hear back, so the same event can arrive twice; this
 * keeps every event counted once.
 */
export async function storeEvents(
  db: Kysely<Database>,
  projectId: string,
  events: readonly NewEvent[],
): Promise<StoreResult> {
  if (events.length === 0) {
    return { inserted: 0, duplicates: 0 };
  }

  const result = await db
    .insertInto("events")
    .values(
      events.map((event) => ({
        project_id: projectId,
        event_id: event.eventId,
        name: event.name,
        occurred_at: event.occurredAt,
        path: event.path,
        referrer: event.referrer,
        utm_source: event.utm?.source,
        utm_medium: event.utm?.medium,
        utm_campaign: event.utm?.campaign,
        utm_term: event.utm?.term,
        utm_content: event.utm?.content,
        properties: event.properties,
        browser: event.client?.browser,
        browser_version: event.client?.browserVersion,
        os: event.client?.os,
        device_type: event.client?.deviceType,
        country: event.location?.country,
        region: event.location?.region,
        city: event.location?.city,
        visitor_id: event.visitorId,
        environment: event.environment,
        release: event.release,
        user_id: event.userId,
      })),
    )
    .onConflict((conflict) => conflict.columns(["project_id", "event_id"]).doNothing())
    .executeTakeFirst();

  const inserted = Number(result.numInsertedOrUpdatedRows ?? 0n);
  return { inserted, duplicates: events.length - inserted };
}
